requireApi(1)

name("Bad Apple")
description("Original 96x72 Bad Apple frames at 30 FPS")

val sizeSetting = slider("Размер", 1.0f, 0.45f, 1.60f, 0.05f)
val opacitySetting = slider("Прозрачность", 1.0f, 0.25f, 1.0f, 0.05f)

val FRAME_COLUMNS = 48
val FRAME_ROWS = 18
val FRAME_WIDTH = 96
val FRAME_HEIGHT = 72
val DISPLAY_WIDTH = FRAME_WIDTH * 2
val DISPLAY_HEIGHT = FRAME_HEIGHT * 2
val FRAME_CELLS = FRAME_COLUMNS * FRAME_ROWS
val FRAME_COUNT = 6572
val FRAME_RATE = 30.0f
val PACKED_SIZE = 897344

// User-supplied 30 FPS Braille frames. Each chunk stays below the JVM
// constant-pool string limit. The stream stores XOR frame differences with
// zero/literal run-length encoding, so all pixels remain lossless.
val FRAME_DATA = arrayOf(
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    ""
)

fun base64Value(character: Char): Int {
    return when (character) {
        in 'A'..'Z' -> character.code - 'A'.code
        in 'a'..'z' -> character.code - 'a'.code + 26
        in '0'..'9' -> character.code - '0'.code + 52
        '+' -> 62
        '/' -> 63
        else -> -1
    }
}

fun decodePackedFrames(): ByteArray {
    val result = ByteArray(PACKED_SIZE)
    var outputIndex = 0
    var accumulator = 0
    var accumulatorBits = 0

    for (chunk in FRAME_DATA) {
        for (character in chunk) {
            if (character == '=') break
            val value = base64Value(character)
            if (value < 0) continue

            accumulator = (accumulator shl 6) or value
            accumulatorBits += 6

            if (accumulatorBits >= 8) {
                accumulatorBits -= 8
                if (outputIndex < result.size) {
                    result[outputIndex++] =
                        ((accumulator shr accumulatorBits) and 0xFF).toByte()
                }
                accumulator = accumulator and ((1 shl accumulatorBits) - 1)
            }
        }
    }

    if (outputIndex != PACKED_SIZE) {
        log.error("Bad Apple data size mismatch: $outputIndex/$PACKED_SIZE")
    }
    return result
}

val packedFrames = decodePackedFrames()
val currentCells = ByteArray(FRAME_CELLS)

var packedPosition = 0
var decodedFrame = -1
var playbackStartTick = 0L

fun resetDecoder() {
    currentCells.fill(0)
    packedPosition = 0
    decodedFrame = -1
}

fun decodeNextFrame(): Boolean {
    if (decodedFrame + 1 >= FRAME_COUNT) return false

    var cellIndex = 0
    while (cellIndex < FRAME_CELLS) {
        if (packedPosition >= packedFrames.size) return false
        val control = packedFrames[packedPosition++].toInt() and 0xFF
        val count = (control and 0x7F) + 1

        if ((control and 0x80) == 0) {
            cellIndex += count
        } else {
            repeat(count) {
                if (
                    cellIndex < FRAME_CELLS &&
                    packedPosition < packedFrames.size
                ) {
                    val difference =
                        packedFrames[packedPosition++].toInt() and 0xFF
                    currentCells[cellIndex] =
                        ((currentCells[cellIndex].toInt() and 0xFF) xor
                            difference).toByte()
                    cellIndex++
                }
            }
        }
    }

    decodedFrame++
    return true
}

fun seekFrame(targetFrame: Int): Boolean {
    if (targetFrame < decodedFrame) resetDecoder()
    while (decodedFrame < targetFrame) {
        if (!decodeNextFrame()) return false
    }
    return true
}

fun braillePixel(pixelX: Int, pixelY: Int): Boolean {
    val cellX = pixelX / 2
    val cellY = pixelY / 4
    val localX = pixelX and 1
    val localY = pixelY and 3
    val bit = when (localY) {
        0 -> if (localX == 0) 0 else 3
        1 -> if (localX == 0) 1 else 4
        2 -> if (localX == 0) 2 else 5
        else -> if (localX == 0) 6 else 7
    }
    val cell = currentCells[cellY * FRAME_COLUMNS + cellX].toInt() and 0xFF
    return (cell and (1 shl bit)) != 0
}

fun sourcePixel(pixelX: Int, pixelY: Int, fallback: Boolean): Boolean {
    if (pixelX !in 0 until FRAME_WIDTH) return fallback
    if (pixelY !in 0 until FRAME_HEIGHT) return fallback
    return braillePixel(pixelX, pixelY)
}

// Scale2x keeps the monochrome image sharp while refining diagonal contours.
fun displayPixel(displayX: Int, displayY: Int): Boolean {
    val sourceX = displayX / 2
    val sourceY = displayY / 2
    val center = braillePixel(sourceX, sourceY)
    val north = sourcePixel(sourceX, sourceY - 1, center)
    val west = sourcePixel(sourceX - 1, sourceY, center)
    val east = sourcePixel(sourceX + 1, sourceY, center)
    val south = sourcePixel(sourceX, sourceY + 1, center)

    if (north == south || west == east) return center

    return when ((displayY and 1) * 2 + (displayX and 1)) {
        0 -> if (west == north) west else center
        1 -> if (north == east) east else center
        2 -> if (west == south) west else center
        else -> if (south == east) east else center
    }
}

fun drawCurrentFrame(
    render: Render,
    panelX: Float,
    panelY: Float,
    panelWidth: Float,
    panelHeight: Float,
    opacity: Float
) {
    val background = Colors.rgba(
        0,
        0,
        0,
        (255.0f * opacity).toInt().coerceIn(0, 255)
    )
    val foreground = Colors.rgba(
        255,
        255,
        255,
        (255.0f * opacity).toInt().coerceIn(0, 255)
    )
    render.rect(panelX, panelY, panelWidth, panelHeight, background)

    val pixelWidth = panelWidth / DISPLAY_WIDTH.toFloat()
    val pixelHeight = panelHeight / DISPLAY_HEIGHT.toFloat()

    for (pixelY in 0 until DISPLAY_HEIGHT) {
        var runStart = -1
        for (pixelX in 0..DISPLAY_WIDTH) {
            val lit = pixelX < DISPLAY_WIDTH && displayPixel(pixelX, pixelY)
            if (lit && runStart < 0) runStart = pixelX

            if (!lit && runStart >= 0) {
                render.rect(
                    panelX + runStart * pixelWidth,
                    panelY + pixelY * pixelHeight,
                    (pixelX - runStart) * pixelWidth + 0.15f,
                    pixelHeight + 0.15f,
                    foreground
                )
                runStart = -1
            }
        }
    }
}

on<Render2DEvent>(priority = Priority.LAST) { event ->
    val elapsedTicks =
        (client.tick() - playbackStartTick).coerceAtLeast(0L).toFloat() +
            event.tickDelta()
    val absoluteFrame = (elapsedTicks * FRAME_RATE / 20.0f).toInt()
    val targetFrame = absoluteFrame % FRAME_COUNT
    if (!seekFrame(targetFrame)) return@on

    val viewportWidth = event.width().toFloat()
    val viewportHeight = event.height().toFloat()
    val maximumWidth = minOf(
        viewportWidth - 32.0f,
        (viewportHeight - 32.0f) * 4.0f / 3.0f
    ).coerceAtLeast(128.0f)
    val panelWidth = minOf(576.0f * sizeSetting.value(), maximumWidth)
    val panelHeight = panelWidth * 3.0f / 4.0f
    val panelX = (viewportWidth - panelWidth) * 0.5f
    val panelY = (viewportHeight - panelHeight) * 0.5f

    drawCurrentFrame(
        event.render(),
        panelX,
        panelY,
        panelWidth,
        panelHeight,
        opacitySetting.value()
    )
}

fun restartPlayback() {
    playbackStartTick = client.tick()
    resetDecoder()
}

button("Перезапустить") {
    restartPlayback()
}

command("badapple") {
    usage("restart | status")
    completes(0) { listOf("restart", "status") }

    runs {
        val elapsed = (client.tick() - playbackStartTick).coerceAtLeast(0L) / 20L
        chat.printPrefixed("Bad Apple", "frame=$decodedFrame/$FRAME_COUNT, ${elapsed}s")
    }

    sub("restart") {
        runs {
            restartPlayback()
            chat.printPrefixed("Bad Apple", "restarted")
        }
    }

    sub("status") {
        runs {
            val elapsed =
                (client.tick() - playbackStartTick).coerceAtLeast(0L) / 20L
            chat.printPrefixed(
                "Bad Apple",
                "frame=$decodedFrame/$FRAME_COUNT, ${elapsed}s, data=${packedFrames.size} bytes"
            )
        }
    }
}

onEnable {
    restartPlayback()
    log.info("Bad Apple enabled: $FRAME_COUNT original frames at 30 FPS")
}

on<WorldLoadEvent> {
    restartPlayback()
}
